// Orchestrator Service — processes a trigger event and decides whether to dispatch
public class NotificationOrchestrator
{
    private readonly IPreferenceClient _preferences;   // gRPC client to Preference Service
    private readonly ITemplateEngine   _templates;    // Scriban-based template renderer
    private readonly IDedupStore        _dedup;        // Redis SET for per-user dedup window
    private readonly IEventBus          _eventBus;     // MassTransit outbox
    private readonly IDateTimeProvider  _clock;

    public async Task ProcessAsync(TriggerEvent evt, CancellationToken ct)
    {
        // 1. Fetch user preferences (cached in Redis by Preference Service)
        var prefs = await _preferences.GetPreferencesAsync(evt.UserId);
        if (prefs == null) return;

        // 2. Check if user has opted out of this category for this channel
        var channelPref = prefs.GetChannelPreference(evt.Category, evt.Channel);
        if (channelPref == OptOutStatus.OptOut) return;

        // 3. Check quiet hours (for non-critical categories only)
        if (channelPref == OptOutStatus.QuietHours && IsInQuietHours(prefs, evt.UserId))
        {
            await RescheduleAfterQuietHours(evt, prefs.QuietHours);
            return;
        }

        // 4. Dedup check: same user + category + entityId within 30 min window
        var dedupKey = string.Format("dedup:{0}:{1}:{2}", evt.UserId, evt.Category, evt.EntityId);
        if (await _dedup.ExistsAsync(dedupKey))
        {
            _logger.LogInformation("Suppressed duplicate notification for {UserId} / {Category} / {EntityId}",
                evt.UserId, evt.Category, evt.EntityId);
            return;
        }
        await _dedup.SetAsync(dedupKey, "1", expiry: TimeSpan.FromMinutes(30));

        // 5. Render template with event payload variables
        var template = await _templates.GetActiveTemplateAsync(evt.Category, evt.Channel);
        var rendered = await _templates.RenderAsync(template, evt.Variables);

        // 6. Publish dispatch command — outbox guarantees delivery even if the process crashes here
        await _eventBus.Publish(new DispatchNotification
        {
            NotificationId = Guid.NewGuid(),
            UserId = evt.UserId,
            Channel = evt.Channel,
            Subject = rendered.Subject,
            Body = rendered.Body,
            Category = evt.Category,
            TriggeredAt = _clock.UtcNow,
            IdempotencyKey = string.Format("{0}:{1}:{2}", evt.UserId, evt.Category, evt.EntityId)
        });
    }

    private bool IsInQuietHours(UserPreferences prefs, string userId)
    {
        var userTz = TimeZoneInfo.FindSystemTimeZoneById(prefs.Timezone);
        var nowInUserTz = TimeZoneInfo.ConvertTime(_clock.UtcNow, userTz);
        return nowInUserTz.TimeOfDay >= prefs.QuietHours.Start
            && nowInUserTz.TimeOfDay <= prefs.QuietHours.End
            && prefs.QuietHours.Enabled;
    }

    private async Task RescheduleAfterQuietHours(TriggerEvent evt, QuietHours quietHours)
    {
        var tz = TimeZoneInfo.FindSystemTimeZoneById(quietHours.Timezone);
        var nowInUserTz = TimeZoneInfo.ConvertTime(_clock.UtcNow, tz);
        var sendAt = nowInUserTz.Date.Add(quietHours.End);
        if (sendAt <= _clock.UtcNow)
            sendAt = sendAt.AddDays(1);

        await _eventBus.Publish(new NotificationScheduled
        {
            OriginalEvent = evt,
            ScheduledAt = sendAt.ToUniversalTime()
        });
    }
}

